-- Runtime-role grants for the MAVLIT API. GENERATED by `python -m pipeline.db_grants`; do not edit by hand.
-- Role mavlit_app (API runtime), schema owner mavlit_user, database mavlit_enrichment_test, schema public.
-- Review it, run it on a scratch copy first, then run it as the owner role (or a superuser). Everything below is one
-- transaction: it either leaves mavlit_app with exactly the planned access or changes nothing. It touches only mavlit_app's own
-- grants (never another role's), only inside this database, and only the objects named here; backup (bak_*) tables,
-- experiment tables and everything not listed stay inaccessible. Safe to run repeatedly (each object is reset first).
-- It does NOT use ALTER DEFAULT PRIVILEGES, and it never changes role memberships or PUBLIC: if the role is a member of
-- another role, holds PUBLIC-derived access, default privileges, owns objects or has elevated attributes, the final
-- audit step aborts the transaction and prints how to fix each finding.
\set ON_ERROR_STOP on
BEGIN;

-- Guard: right database, run by the owner or a superuser, role exists.
DO $guard$
BEGIN
    IF current_database() <> 'mavlit_enrichment_test' THEN
        RAISE EXCEPTION 'this script is for database mavlit_enrichment_test, not %', current_database();
    END IF;
    IF NOT (pg_has_role(current_user, 'mavlit_user', 'USAGE') OR (SELECT rolsuper FROM pg_roles WHERE rolname = current_user)) THEN
        RAISE EXCEPTION 'run this script as mavlit_user (or a superuser), not %', current_user;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'mavlit_app') THEN
        RAISE EXCEPTION 'role mavlit_app does not exist';
    END IF;
END
$guard$;

-- Planned tables and views must exist (run the migrations first).
DO $planned$
DECLARE missing text;
BEGIN
    SELECT string_agg(p.obj, ', ' ORDER BY p.obj) INTO missing
    FROM (VALUES ('apify_usage', 'SELECT, INSERT'), ('brand_contacts', 'SELECT, INSERT, UPDATE, DELETE'), ('brand_instagram_users', 'SELECT, INSERT, UPDATE, DELETE'), ('brand_match_profile', 'SELECT, INSERT, UPDATE, DELETE'), ('brands_niches', 'SELECT, INSERT, UPDATE, DELETE'), ('brands_raw', 'SELECT, INSERT, UPDATE, DELETE'), ('contact_reveals', 'SELECT, INSERT'), ('content_creator_re', 'SELECT, INSERT, UPDATE, DELETE'), ('contract_reviews', 'SELECT, INSERT, UPDATE, DELETE'), ('creator_brand_llm_rankings', 'SELECT, INSERT, DELETE'), ('creator_brand_llm_v3_rankings', 'SELECT, INSERT, DELETE'), ('creator_instagram_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('creator_llm_cost', 'SELECT'), ('creator_niches', 'SELECT, INSERT, UPDATE, DELETE'), ('creator_profiles', 'SELECT, INSERT, UPDATE'), ('early_access_signups', 'SELECT, INSERT, UPDATE, DELETE'), ('facebook_branded_content_checks', 'SELECT, INSERT, UPDATE, DELETE'), ('feature_locks', 'SELECT, INSERT, DELETE'), ('feature_usage', 'SELECT, INSERT, UPDATE'), ('initial_brand_score', 'SELECT, INSERT, UPDATE, DELETE'), ('instagram_creator_commenters', 'SELECT, INSERT, UPDATE, DELETE'), ('instagram_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('instagram_users', 'SELECT, INSERT, UPDATE, DELETE'), ('llm_usage', 'SELECT, INSERT'), ('login_failures', 'SELECT, INSERT, DELETE'), ('meta_ads', 'SELECT, INSERT, UPDATE, DELETE'), ('own_brand_jobs', 'SELECT, INSERT, UPDATE, DELETE'), ('pitches', 'SELECT, INSERT, UPDATE, DELETE'), ('prompts', 'SELECT, INSERT, UPDATE, DELETE'), ('rate_estimates', 'SELECT, INSERT, UPDATE, DELETE'), ('saved_brands', 'SELECT, INSERT, UPDATE, DELETE'), ('test_brands_with_instagram_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('test_creator_brand_partnership_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('test_niches', 'SELECT, INSERT, UPDATE, DELETE'), ('youtube_sponsorships', 'SELECT, INSERT, UPDATE, DELETE')) AS p(obj, privs)
    WHERE to_regclass(quote_ident('public') || '.' || quote_ident(p.obj)) IS NULL;
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'planned tables or views do not exist yet: ' || missing || ' - run the migrations first (python -m pipeline.migrate)';
    END IF;
END
$planned$;

-- Database: reset the role's own direct privileges, then CONNECT.
DO $database$
BEGIN
    EXECUTE 'REVOKE ALL ON DATABASE ' || quote_ident(current_database()) || ' FROM ' || quote_ident('mavlit_app');
    EXECUTE 'GRANT CONNECT ON DATABASE ' || quote_ident(current_database()) || ' TO ' || quote_ident('mavlit_app');
END
$database$;

-- Schema, tables and the view (privileges = routes and jobs + SQLAdmin; see pipeline/db_grants.py).
REVOKE ALL ON SCHEMA "public" FROM "mavlit_app";
GRANT USAGE ON SCHEMA "public" TO "mavlit_app";
