-- Sequences owned by the tables above (serial / identity ids): USAGE lets inserts take the next value.
DO $sequences$
DECLARE seq record;
BEGIN
    FOR seq IN
        SELECT sn.nspname AS seq_schema, s.relname AS seq_name FROM pg_class s JOIN pg_namespace sn ON sn.oid = s.relnamespace
        WHERE s.oid IN (SELECT s.oid FROM pg_class s JOIN pg_depend d ON d.objid = s.oid AND d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass AND d.deptype IN ('a', 'i') JOIN pg_class t ON t.oid = d.refobjid JOIN pg_namespace tn ON tn.oid = t.relnamespace WHERE s.relkind = 'S' AND tn.nspname = 'public' AND t.relname IN ('apify_usage', 'brand_contacts', 'brand_instagram_users', 'brand_match_profile', 'brands_niches', 'brands_raw', 'contact_reveals', 'content_creator_re', 'contract_reviews', 'creator_brand_llm_rankings', 'creator_brand_llm_v3_rankings', 'creator_instagram_posts', 'creator_niches', 'creator_profiles', 'early_access_signups', 'facebook_branded_content_checks', 'feature_locks', 'feature_usage', 'initial_brand_score', 'instagram_creator_commenters', 'instagram_posts', 'instagram_users', 'llm_usage', 'login_failures', 'meta_ads', 'own_brand_jobs', 'pitches', 'prompts', 'rate_estimates', 'saved_brands', 'test_brands_with_instagram_posts', 'test_creator_brand_partnership_posts', 'test_niches', 'youtube_sponsorships')) ORDER BY 1, 2
    LOOP
        EXECUTE 'REVOKE ALL ON SEQUENCE ' || quote_ident(seq.seq_schema) || '.' || quote_ident(seq.seq_name) || ' FROM ' || quote_ident('mavlit_app');
        EXECUTE 'GRANT USAGE ON SEQUENCE ' || quote_ident(seq.seq_schema) || '.' || quote_ident(seq.seq_name) || ' TO ' || quote_ident('mavlit_app');
    END LOOP;
END
$sequences$;

-- The role's own direct grants outside the plan (other tables, views, sequences, schemas) are revoked; nobody else's are.
DO $stray$
DECLARE obj record; app oid;
BEGIN
    SELECT oid INTO app FROM pg_roles WHERE rolname = 'mavlit_app';
    FOR obj IN
        SELECT n.nspname AS sch, c.relname AS rel, c.relkind AS kind
        FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)' AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S')
          AND NOT (n.nspname = 'public' AND ((c.relkind <> 'S' AND c.relname IN ('apify_usage', 'brand_contacts', 'brand_instagram_users', 'brand_match_profile', 'brands_niches', 'brands_raw', 'contact_reveals', 'content_creator_re', 'contract_reviews', 'creator_brand_llm_rankings', 'creator_brand_llm_v3_rankings', 'creator_instagram_posts', 'creator_llm_cost', 'creator_niches', 'creator_profiles', 'early_access_signups', 'facebook_branded_content_checks', 'feature_locks', 'feature_usage', 'initial_brand_score', 'instagram_creator_commenters', 'instagram_posts', 'instagram_users', 'llm_usage', 'login_failures', 'meta_ads', 'own_brand_jobs', 'pitches', 'prompts', 'rate_estimates', 'saved_brands', 'test_brands_with_instagram_posts', 'test_creator_brand_partnership_posts', 'test_niches', 'youtube_sponsorships')) OR c.oid IN (SELECT s.oid FROM pg_class s JOIN pg_depend d ON d.objid = s.oid AND d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass AND d.deptype IN ('a', 'i') JOIN pg_class t ON t.oid = d.refobjid JOIN pg_namespace tn ON tn.oid = t.relnamespace WHERE s.relkind = 'S' AND tn.nspname = 'public' AND t.relname IN ('apify_usage', 'brand_contacts', 'brand_instagram_users', 'brand_match_profile', 'brands_niches', 'brands_raw', 'contact_reveals', 'content_creator_re', 'contract_reviews', 'creator_brand_llm_rankings', 'creator_brand_llm_v3_rankings', 'creator_instagram_posts', 'creator_niches', 'creator_profiles', 'early_access_signups', 'facebook_branded_content_checks', 'feature_locks', 'feature_usage', 'initial_brand_score', 'instagram_creator_commenters', 'instagram_posts', 'instagram_users', 'llm_usage', 'login_failures', 'meta_ads', 'own_brand_jobs', 'pitches', 'prompts', 'rate_estimates', 'saved_brands', 'test_brands_with_instagram_posts', 'test_creator_brand_partnership_posts', 'test_niches', 'youtube_sponsorships'))))
          AND (EXISTS (SELECT 1 FROM aclexplode(c.relacl) a WHERE a.grantee = app)
               OR EXISTS (SELECT 1 FROM pg_attribute at, aclexplode(at.attacl) a WHERE at.attrelid = c.oid AND a.grantee = app))
        ORDER BY 1, 2
    LOOP
        EXECUTE 'REVOKE ALL ON ' || CASE WHEN obj.kind = 'S' THEN 'SEQUENCE ' ELSE 'TABLE ' END || quote_ident(obj.sch) || '.' || quote_ident(obj.rel) || ' FROM ' || quote_ident('mavlit_app');
        RAISE NOTICE USING MESSAGE = 'revoked a direct grant outside the plan from ' || 'mavlit_app' || ' on ' || obj.sch || '.' || obj.rel;
    END LOOP;
    FOR obj IN
        SELECT n.nspname AS sch FROM pg_namespace n
        WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)' AND n.nspname <> 'public' AND EXISTS (SELECT 1 FROM aclexplode(n.nspacl) a WHERE a.grantee = app)
        ORDER BY 1
    LOOP
        EXECUTE 'REVOKE ALL ON SCHEMA ' || quote_ident(obj.sch) || ' FROM ' || quote_ident('mavlit_app');
        RAISE NOTICE USING MESSAGE = 'revoked a direct schema grant outside the plan from ' || 'mavlit_app' || ' on ' || obj.sch;
    END LOOP;
END
$stray$;

-- Audit: the role's EFFECTIVE access (direct, inherited through membership, PUBLIC) must equal the plan, or abort.
DO $audit$
DECLARE report text;
BEGIN
    SELECT string_agg('  - ' || object || ': ' || problem || E'\n      fix: ' || fix, E'\n' ORDER BY object, problem) INTO report
    FROM (
WITH app AS (SELECT oid, rolname FROM pg_roles WHERE rolname = 'mavlit_app'),
plan(obj, privs) AS (VALUES ('apify_usage', 'SELECT, INSERT'), ('brand_contacts', 'SELECT, INSERT, UPDATE, DELETE'), ('brand_instagram_users', 'SELECT, INSERT, UPDATE, DELETE'), ('brand_match_profile', 'SELECT, INSERT, UPDATE, DELETE'), ('brands_niches', 'SELECT, INSERT, UPDATE, DELETE'), ('brands_raw', 'SELECT, INSERT, UPDATE, DELETE'), ('contact_reveals', 'SELECT, INSERT'), ('content_creator_re', 'SELECT, INSERT, UPDATE, DELETE'), ('contract_reviews', 'SELECT, INSERT, UPDATE, DELETE'), ('creator_brand_llm_rankings', 'SELECT, INSERT, DELETE'), ('creator_brand_llm_v3_rankings', 'SELECT, INSERT, DELETE'), ('creator_instagram_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('creator_llm_cost', 'SELECT'), ('creator_niches', 'SELECT, INSERT, UPDATE, DELETE'), ('creator_profiles', 'SELECT, INSERT, UPDATE'), ('early_access_signups', 'SELECT, INSERT, UPDATE, DELETE'), ('facebook_branded_content_checks', 'SELECT, INSERT, UPDATE, DELETE'), ('feature_locks', 'SELECT, INSERT, DELETE'), ('feature_usage', 'SELECT, INSERT, UPDATE'), ('initial_brand_score', 'SELECT, INSERT, UPDATE, DELETE'), ('instagram_creator_commenters', 'SELECT, INSERT, UPDATE, DELETE'), ('instagram_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('instagram_users', 'SELECT, INSERT, UPDATE, DELETE'), ('llm_usage', 'SELECT, INSERT'), ('login_failures', 'SELECT, INSERT, DELETE'), ('meta_ads', 'SELECT, INSERT, UPDATE, DELETE'), ('own_brand_jobs', 'SELECT, INSERT, UPDATE, DELETE'), ('pitches', 'SELECT, INSERT, UPDATE, DELETE'), ('prompts', 'SELECT, INSERT, UPDATE, DELETE'), ('rate_estimates', 'SELECT, INSERT, UPDATE, DELETE'), ('saved_brands', 'SELECT, INSERT, UPDATE, DELETE'), ('test_brands_with_instagram_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('test_creator_brand_partnership_posts', 'SELECT, INSERT, UPDATE, DELETE'), ('test_niches', 'SELECT, INSERT, UPDATE, DELETE'), ('youtube_sponsorships', 'SELECT, INSERT, UPDATE, DELETE')),
planned_seq AS (SELECT s.oid FROM pg_class s JOIN pg_depend d ON d.objid = s.oid AND d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass AND d.deptype IN ('a', 'i') JOIN pg_class t ON t.oid = d.refobjid JOIN pg_namespace tn ON tn.oid = t.relnamespace WHERE s.relkind = 'S' AND tn.nspname = 'public' AND t.relname IN ('apify_usage', 'brand_contacts', 'brand_instagram_users', 'brand_match_profile', 'brands_niches', 'brands_raw', 'contact_reveals', 'content_creator_re', 'contract_reviews', 'creator_brand_llm_rankings', 'creator_brand_llm_v3_rankings', 'creator_instagram_posts', 'creator_niches', 'creator_profiles', 'early_access_signups', 'facebook_branded_content_checks', 'feature_locks', 'feature_usage', 'initial_brand_score', 'instagram_creator_commenters', 'instagram_posts', 'instagram_users', 'llm_usage', 'login_failures', 'meta_ads', 'own_brand_jobs', 'pitches', 'prompts', 'rate_estimates', 'saved_brands', 'test_brands_with_instagram_posts', 'test_creator_brand_partnership_posts', 'test_niches', 'youtube_sponsorships')),
rels AS (
    SELECT c.oid, c.relname, c.relkind, c.relowner, n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)' AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S')
),
held AS (
    SELECT r.nspname, r.relname, r.relkind, r.oid, p.priv
    FROM rels r CROSS JOIN app CROSS JOIN (VALUES ('SELECT'), ('INSERT'), ('UPDATE'), ('DELETE'), ('TRUNCATE'), ('REFERENCES'), ('TRIGGER'), ('MAINTAIN')) p(priv)
    WHERE r.relkind <> 'S' AND CASE
              -- MAINTAIN (VACUUM, ANALYZE, REINDEX, LOCK ...) exists from PostgreSQL 17; the nested CASE never evaluates it on older servers
              WHEN p.priv = 'MAINTAIN' THEN (CASE WHEN current_setting('server_version_num')::int >= 170000 THEN has_table_privilege(app.oid, r.oid, p.priv) ELSE false END)
              WHEN p.priv IN ('SELECT', 'INSERT', 'UPDATE', 'REFERENCES') THEN has_any_column_privilege(app.oid, r.oid, p.priv)
              ELSE has_table_privilege(app.oid, r.oid, p.priv) END
    UNION ALL
    SELECT r.nspname, r.relname, r.relkind, r.oid, q.priv
    FROM rels r CROSS JOIN app CROSS JOIN (VALUES ('USAGE'), ('SELECT'), ('UPDATE')) q(priv)
    WHERE r.relkind = 'S' AND has_sequence_privilege(app.oid, r.oid, q.priv)
),
findings AS (
    -- 1. access the plan does not give: unplanned objects, or planned objects with extra privileges
    SELECT 'violation' AS severity, h.nspname || '.' || h.relname AS object,
           'holds ' || h.priv || ' (directly, through a role membership, or through PUBLIC), which is not in the plan' AS problem,
           'if it was granted directly, re-run the grant step (it revokes the role''s own direct grants); otherwise ' || 'revoke it from PUBLIC on that object yourself (it also affects other roles), or classify the object in pipeline/db_grants.py' AS fix
    FROM held h
    WHERE NOT (h.nspname = 'public' AND (
              (h.relkind <> 'S' AND EXISTS (SELECT 1 FROM plan p WHERE p.obj = h.relname AND h.priv = ANY (string_to_array(p.privs, ', '))))
           OR (h.relkind = 'S' AND h.oid IN (SELECT oid FROM planned_seq) AND h.priv = 'USAGE')))
    UNION ALL
    -- 2. planned access that is missing
    SELECT 'violation', 'public' || '.' || p.obj, 'is missing ' || x.priv, 'run the grant step again'
    FROM plan p CROSS JOIN app CROSS JOIN LATERAL unnest(string_to_array(p.privs, ', ')) AS x(priv)
    WHERE to_regclass(quote_ident('public') || '.' || quote_ident(p.obj)) IS NOT NULL
      AND NOT has_table_privilege(app.oid, (quote_ident('public') || '.' || quote_ident(p.obj))::regclass, x.priv)
    UNION ALL
    SELECT 'violation', s.relname, 'is missing USAGE', 'run the grant step again'
    FROM pg_class s CROSS JOIN app WHERE s.oid IN (SELECT oid FROM planned_seq) AND NOT has_sequence_privilege(app.oid, s.oid, 'USAGE')
    UNION ALL
    -- 3. role attributes and memberships (inherited access cannot be undone by revoking direct grants)
    SELECT 'violation', app.rolname, 'has the elevated attribute ' || a.attr,
           'ALTER ROLE ' || app.rolname || ' NO' || a.attr
    FROM app CROSS JOIN LATERAL (
        SELECT 'SUPERUSER' AS attr FROM pg_roles WHERE oid = app.oid AND rolsuper UNION ALL
        SELECT 'CREATEDB' FROM pg_roles WHERE oid = app.oid AND rolcreatedb UNION ALL
        SELECT 'CREATEROLE' FROM pg_roles WHERE oid = app.oid AND rolcreaterole UNION ALL
        SELECT 'REPLICATION' FROM pg_roles WHERE oid = app.oid AND rolreplication UNION ALL
        SELECT 'BYPASSRLS' FROM pg_roles WHERE oid = app.oid AND rolbypassrls) a
    UNION ALL
    SELECT 'violation', app.rolname, 'is a member of the role ' || g.rolname || ' (it can use, or SET ROLE to, everything that role can)',
           'REVOKE ' || quote_ident(g.rolname) || ' FROM ' || quote_ident(app.rolname) || ' (as a superuser or the grantor), then run this again'
    FROM app JOIN pg_roles g ON g.oid <> app.oid AND pg_has_role(app.oid, g.oid, 'MEMBER')
    UNION ALL
    -- 4. default privileges and ownership
    SELECT 'violation', 'default privileges of ' || d.defaclrole::regrole::text,
           'grant ' || x.privilege_type || ' on future ' || CASE d.defaclobjtype WHEN 'r' THEN 'tables' WHEN 'S' THEN 'sequences' WHEN 'f' THEN 'functions' WHEN 'T' THEN 'types' ELSE 'objects' END || ' to the role',
           'remove the default-privilege entry for ' || 'mavlit_app' || ' held under the role ' || d.defaclrole::regrole::text || ' (see pg_default_acl): it would expose every future table'
    FROM pg_default_acl d CROSS JOIN app CROSS JOIN LATERAL aclexplode(d.defaclacl) x WHERE x.grantee = app.oid
    UNION ALL
    SELECT 'violation', r.nspname || '.' || r.relname, 'is owned by the runtime role', 'ALTER TABLE ... OWNER TO the owner role'
    FROM rels r JOIN app ON r.relowner = app.oid
    UNION ALL
    SELECT 'violation', 'schema ' || n.nspname, 'is owned by the runtime role', 'ALTER SCHEMA ... OWNER TO the owner role'
    FROM pg_namespace n JOIN app ON n.nspowner = app.oid WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)'
    UNION ALL
    SELECT 'violation', 'database ' || current_database(), 'is owned by the runtime role', 'ALTER DATABASE ... OWNER TO the owner role'
    FROM pg_database d JOIN app ON d.datdba = app.oid WHERE d.datname = current_database()
    UNION ALL
    -- 5. schemas and the database
    SELECT 'violation', 'schema ' || n.nspname, 'allows the role to ' || x.priv || ' (not in the plan)',
           'revoke it (the grant step removes direct schema grants; PUBLIC grants must be revoked by you)'
    FROM pg_namespace n CROSS JOIN app CROSS JOIN (VALUES ('CREATE'), ('USAGE')) x(priv)
    WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)' AND has_schema_privilege(app.oid, n.oid, x.priv)
      AND NOT (n.nspname = 'public' AND x.priv = 'USAGE')
    UNION ALL
    SELECT 'violation', 'schema ' || 'public', 'is missing USAGE', 'run the grant step again'
    FROM app WHERE NOT has_schema_privilege(app.oid, 'public', 'USAGE')
    UNION ALL
    SELECT 'violation', 'database ' || current_database(), 'allows the role to CREATE schemas', 'REVOKE CREATE ON DATABASE ' || quote_ident(current_database()) || ' FROM ' || 'mavlit_app' || ' (and from PUBLIC if it comes from there)'
    FROM app WHERE has_database_privilege(app.oid, current_database(), 'CREATE')
    UNION ALL
    SELECT 'violation', 'database ' || current_database(), 'is missing CONNECT', 'run the grant step again'
    FROM app WHERE NOT has_database_privilege(app.oid, current_database(), 'CONNECT')
    UNION ALL
    SELECT 'warning', 'database ' || current_database(), 'allows the role to create TEMPORARY tables (a PUBLIC default; nothing in the API uses them)',
           'optional: REVOKE TEMPORARY ON DATABASE ' || quote_ident(current_database()) || ' FROM PUBLIC'
    FROM app WHERE has_database_privilege(app.oid, current_database(), 'TEMPORARY')
)
SELECT severity, object, problem, fix FROM findings ORDER BY severity DESC, object, problem
    ) f WHERE severity = 'violation';
    IF report IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'the runtime role mavlit_app would not have exactly the planned access; nothing was changed:' || E'\n' || report;
    END IF;
END
$audit$;

COMMIT;

-- Optional hardening, NOT part of the grants above (it changes PUBLIC, so decide separately):
--   PostgreSQL 15+ already denies CREATE on schema public to PUBLIC; on older versions run:
--     REVOKE CREATE ON SCHEMA public FROM PUBLIC;
--   Temporary tables are allowed to PUBLIC by default (nothing in the API uses them; the audit reports it as a warning):
--     REVOKE TEMPORARY ON DATABASE mavlit_enrichment_test FROM PUBLIC;
-- Not granted on purpose: TRUNCATE, REFERENCES, TRIGGER, CREATE, ownership, superuser, and every table not listed above.
